E('n_no_heir',3,3,290,'Без следующего имени','В родословной нет живого допустимого преемника. Совет не может выдумать наследника. Династический брак и новый ребёнок могут спасти дом; если этого не случится, пресечение рода останется настоящей угрозой.','throne',[
 C('Открыть двор для брачных переговоров','25 золота; верность двора +5, престиж +4. Брак нужно заключить через меню династии.',cost={'gold':25},effects={'loyalty':5},politics={'dynasty_prestige':4}),C('Укрепить доверие к действующему правителю','Легитимность +6, власть +5.',effects={'legitimacy':6},politics={'royal_authority':5})],condition='no_heir')
E('n_coup',3,4,310,'Печати королевской канцелярии','В канцелярии проверяют, чьи приказы исполняются без подписи короля. Если лояльность претендентов рухнула, их сторонники могут поднять настоящие владения. Если компромисс удержал дом, чистка лишь создаст новых врагов.','conspiracy',[
 C('Провести открытое разбирательство','35 золота; легитимность +5, верность двора +5; власть +4.',cost={'gold':35},effects={'legitimacy':5,'loyalty':5},politics={'royal_authority':4},flags={'coup_checked':True}),C('Примирить недовольных','45 золота; Михаил и Виктор +15 верности, знать +8; власть −7.',cost={'gold':45},loyalty={'mikhail':15,'victor':15},politics={'noble_support':8,'royal_authority':-7},flags={'coup_checked':True}),C('Ответить угрозой конфискации','Власть +12; верность двора −15 и знать −10. При низкой легитимности риск вооружённого конфликта вырастет.',effects={'loyalty':-15},politics={'royal_authority':12,'noble_support':-10})])
E('n_horizon',3,5,330,'За стенами Хаймира','Корона пережила первые испытания. Теперь совет обсуждает, что делать с обретённой силой: стать центром объединения земель или гарантом мира между ними. Ни один советник не завоюет провинции вместо вас.','palace',[
 C('Объявить курс на объединение','Легитимность +4, власть +8; восточная претензия, если там ещё существует государство.',effects={'legitimacy':4},politics={'royal_authority':8},op='expansion'),C('Провозгласить мир королевских дорог','50 золота; отношения с соседями +10, поддержка знати +8.',cost={'gold':50},politics={'noble_support':8},op='neighbors'),C('Укрепить дом прежде границ','Стабильность +5 и верность родни +8.',effects={'stability':5},loyalty={'mikhail':8,'victor':8})])
